// ---- NYC DOB / ECB common violation codes (starter set; official real codes) ----
// Source: NYC Dept of Buildings ECB violation categories. Prefixed "DOB-" so
// staff can tell them apart from HPD/MDL codes at a glance.
export const DOB_VIOLATION_CODES: ViolationCode[] = [
  { code: 'DOB-01', desc: 'DOB: Work without a permit', abstract: 'Work being performed without a required DOB permit.', hint: 'C' },
  { code: 'DOB-02', desc: 'DOB: Failure to maintain building in code-compliant manner', abstract: 'Building not maintained per NYC Construction/Administrative Code.', hint: 'B' },
  { code: 'DOB-03', desc: 'DOB: Unsafe / hazardous building condition', abstract: 'Structural or facade condition dangerous to occupants or public.', hint: 'C' },
  { code: 'DOB-04', desc: 'DOB: Illegal conversion / occupancy contrary to Certificate of Occupancy', abstract: 'Use or occupancy not permitted by the C of O.', hint: 'C' },
  { code: 'DOB-05', desc: 'DOB: Elevator not maintained / no valid inspection', abstract: 'Elevator out of compliance or overdue inspection.', hint: 'B' },
  { code: 'DOB-06', desc: 'DOB: Boiler not maintained / no valid inspection', abstract: 'Boiler out of compliance or overdue inspection.', hint: 'B' },
  { code: 'DOB-07', desc: 'DOB: Failure to maintain gas piping / illegal gas work', abstract: 'Gas system condition or unpermitted gas work.', hint: 'C' },
  { code: 'DOB-08', desc: 'DOB: Facade / exterior wall unsafe (Local Law 11 / FISP)', abstract: 'Unsafe exterior wall or appurtenance.', hint: 'C' },
  { code: 'DOB-09', desc: 'DOB: Fire protection / egress obstruction', abstract: 'Blocked egress, missing fire-rated separation, or standpipe/sprinkler defect.', hint: 'C' },
  { code: 'DOB-10', desc: 'DOB: Failure to comply with Commissioner\'s order / stop-work order', abstract: 'Work continued after a DOB order or SWO.', hint: 'C' },
  { code: 'DOB-11', desc: 'DOB: Defective / illegal plumbing work', abstract: 'Plumbing condition or unpermitted plumbing work.', hint: 'B' },
  { code: 'DOB-12', desc: 'DOB: Defective / illegal electrical work', abstract: 'Electrical hazard or unpermitted electrical work.', hint: 'C' },
];

const ALL_VIOLATION_CODES: ViolationCode[] = [...VIOLATION_CODES, ...DOB_VIOLATION_CODES];

const CODE_INDEX: Record<string, ViolationCode> = Object.fromEntries(
  ALL_VIOLATION_CODES.map((c) => [c.code.trim().toUpperCase(), c]),
);

export function lookupViolationCode(code: string): ViolationCode | null {
  return CODE_INDEX[(code || "").trim().toUpperCase()] || null;
}

// A compact catalog string for prompting the model to pick a real code.
export function violationCodeCatalog(): string {
  return ALL_VIOLATION_CODES.map((c) => c.code + ": " + (c.abstract || c.desc).slice(0, 80) + (c.hint ? " [" + c.hint + "]" : "")).join("\n");
}
